import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.CuUVYbLV.js";const k=JSON.parse('{"title":"04 把角色变成团队","description":"教程第 04 章：在 role.yaml 里用 subagents 声明 coder、reviewer、doc-writer 三个子代理，让父角色把评审任务派出去。","frontmatter":{"title":"04 把角色变成团队","description":"教程第 04 章：在 role.yaml 里用 subagents 声明 coder、reviewer、doc-writer 三个子代理，让父角色把评审任务派出去。"},"headers":[],"relativePath":"02-Guide/tutorial/04-team.md","filePath":"02-Guide/tutorial/04-team.md"}'),t={name:"02-Guide/tutorial/04-team.md"};function o(l,s,d,p,c,r){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="_04-把角色变成团队-subagents" tabindex="-1">04 把角色变成团队（Subagents） <a class="header-anchor" href="#_04-把角色变成团队-subagents" aria-label="Permalink to &quot;04 把角色变成团队（Subagents）&quot;">​</a></h1><p>这一章把单个 <code>code-reviewer</code> 扩成一个能分工的团队：父角色留在原位，另外声明 <code>coder</code>、<code>reviewer</code>、<code>doc-writer</code> 三个<strong>子代理（subagent，父角色可以委托任务的子级代理，拥有自己的系统提示词与独立会话）</strong>。走完这一章，父角色能把一件事拆给三个人并汇总。</p><blockquote><p>前置：<a href="/rolebox-docs/02-Guide/tutorial/03-functions.html">教程 03 用函数改变行为</a>（<code>~/rolebox-lab/rolebox/code-reviewer</code>，已有技能、引用文档与自定义函数）｜下一章：<a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">05 用图引擎编排团队</a>｜字段全表：<a href="/rolebox-docs/02-Guide/subagents.html">子代理</a></p></blockquote><h2 id="本章造什么" tabindex="-1">本章造什么 <a class="header-anchor" href="#本章造什么" aria-label="Permalink to &quot;本章造什么&quot;">​</a></h2><p>三名子代理各管一段：<code>Coder</code> 实现、<code>Reviewer</code> 审查、<code>Doc-Writer</code> 定稿。声明它们只是往 <code>role.yaml</code> 里加一段 YAML；父角色怎么把活派出去、怎么收回结果，是第 05 章的主题。这一章先让团队被注册，再让你看到父角色眼里的它。</p><h2 id="第-1-步-把-subagents-写进-role-yaml" tabindex="-1">第 1 步：把 subagents: 写进 role.yaml <a class="header-anchor" href="#第-1-步-把-subagents-写进-role-yaml" aria-label="Permalink to &quot;第 1 步：把 subagents: 写进 role.yaml&quot;">​</a></h2><p>打开 <code>~/rolebox-lab/rolebox/code-reviewer/role.yaml</code>，在顶层（与 <code>name:</code>、<code>skills:</code>、<code>functions:</code> 同级）加入这段：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subagents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Coder</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">按需求实现代码改动</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      You are a senior developer. Write clean, testable code.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      改动尽量小、可回滚；回复里列出改动的文件与验证方式。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Reviewer</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">按项目约定审查代码</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      You review code for correctness, style, and edge cases.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      逐条给出「问题 / 位置 / 建议」；没有发现问题时也明确说明。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Doc-Writer</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">把改动写成面向使用者的说明</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      You write user-facing documentation for code changes.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      只写读者需要知道的内容，不重复实现细节。</span></span></code></pre></div><p>三个字段各有分工：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>必填。显示名，同时决定子代理 id：名字转小写、空格换成连字符，再拼成 <code>&lt;角色 id&gt;--&lt;名字&gt;</code>，例如 <code>code-reviewer--coder</code></td></tr><tr><td><code>description</code></td><td>string</td><td>父角色选择子代理时看到的一句话说明</td></tr><tr><td><code>prompt</code></td><td>string</td><td>必填，也可以改用 <code>prompt_file</code> 指向一份提示词文件</td></tr></tbody></table><p>子代理还接受与角色相同的可选字段（<code>model</code>、<code>temperature</code>、<code>permission</code>、<code>tools</code>、<code>skills</code>、<code>functions</code> 等）。<strong>没有显式写出的字段沿用父角色的取值</strong>，可继承的是 <code>model</code>、<code>color</code>、<code>variant</code>、<code>temperature</code>、<code>top_p</code>、<code>permission</code>、<code>tools</code>。文件式声明（<code>subagents/&lt;名字&gt;/role.yaml</code>）与内联声明可以混用，完整字段表见<a href="/rolebox-docs/02-Guide/subagents.html">子代理</a>。</p><h2 id="第-2-步-让改动生效" tabindex="-1">第 2 步：让改动生效 <a class="header-anchor" href="#第-2-步-让改动生效" aria-label="Permalink to &quot;第 2 步：让改动生效&quot;">​</a></h2><p>角色目录在 harness 启动时读取，所以重启会话即可（<a href="/rolebox-docs/02-Guide/tutorial/01-install.html">教程 01</a> 讲过：本地角色不经过锁文件）。<code>rolebox sync</code> 面向的是从注册中心安装的角色，本地角色调用它会得到零条：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（本地角色不在锁文件里时）：</span></span>
<span class="line"><span>Synced 0 roles to opencode</span></span></code></pre></div><p>重启后，三个子代理会随角色一起注册进 harness：它们是 <code>mode: subagent</code> 的代理，由父角色派活调用。</p><h2 id="第-3-步-看父角色眼里的团队" tabindex="-1">第 3 步：看父角色眼里的团队 <a class="header-anchor" href="#第-3-步-看父角色眼里的团队" aria-label="Permalink to &quot;第 3 步：看父角色眼里的团队&quot;">​</a></h2><p>新建会话、选中 <code>code-reviewer</code>，问它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你现在有哪几个子代理？分别负责什么？</span></span></code></pre></div><p>rolebox 会把每个子代理的 id、名字与说明注入父角色的系统提示词（<code>&lt;available_subagents&gt;</code> 段），父角色据此认人：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，措辞随模型变化）：</span></span>
<span class="line"><span>我有三个子代理：</span></span>
<span class="line"><span>- code-reviewer--coder —— 按需求实现代码改动</span></span>
<span class="line"><span>- code-reviewer--reviewer —— 按项目约定审查代码</span></span>
<span class="line"><span>- code-reviewer--doc-writer —— 把改动写成面向使用者的说明</span></span></code></pre></div><p>如果三个都没出现，回到第 1 步检查缩进与必填字段：解析器对不合法的条目<strong>只记日志、不报错</strong>（缺 <code>name</code>、缺 <code>prompt</code>/<code>prompt_file</code>、<code>name</code> 里含 <code>--</code> 的条目都会被静默丢掉）。</p><h2 id="第-4-步-派一个评审任务" tabindex="-1">第 4 步：派一个评审任务 <a class="header-anchor" href="#第-4-步-派一个评审任务" aria-label="Permalink to &quot;第 4 步：派一个评审任务&quot;">​</a></h2><p>现在给父角色一件真实的事，让它自己拆：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 ~/rolebox-lab 下写一个 scripts/hello.sh，打印一行问候。</span></span>
<span class="line"><span>把它跑成一条流水线：coder 先实现，reviewer 接着审，</span></span>
<span class="line"><span>doc-writer 最后写一段面向使用者的说明。</span></span>
<span class="line"><span>每一步都保留产出，三个人都跑完再给我汇总。</span></span></code></pre></div><p>父角色不会同时扮演三个角色：它把每件事建模成一个<strong>图节点（node，一次派发单元，形状是 <code>{agent, prompt}</code> 元组）</strong>，交给图引擎派给对应的子代理。这个回合里你只看到它把图跑起来（<code>graph_run</code> 立即返回、不等待），回合结束后引擎注入 <code>[GRAPH COMPLETE]</code>，下一回合它拿到三份产出，再写成给你的汇总：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，随模型与任务变化）：</span></span>
<span class="line"><span>父角色（第 1 回合）：已把任务拆成 implement → review → document 三个节点，图已运行。</span></span>
<span class="line"><span>&lt;system-reminder&gt;</span></span>
<span class="line"><span>[GRAPH COMPLETE]</span></span>
<span class="line"><span>graph: hello-script</span></span>
<span class="line"><span>phase: complete</span></span>
<span class="line"><span>nodes: completed=3</span></span>
<span class="line"><span>&lt;/system-reminder&gt;</span></span>
<span class="line"><span>父角色（第 2 回合）：汇总——coder 写了 scripts/hello.sh；reviewer 指出缺少可执行权限；</span></span>
<span class="line"><span>doc-writer 的说明是「运行 bash scripts/hello.sh 即可看到问候」。</span></span></code></pre></div><p>父角色这一回合究竟调用了哪几个工具、每个工具返回什么、结果怎么读回来，是下一章的全部内容。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ul><li><strong><code>subagents:</code> 缩进错位</strong>：它必须是 <code>role.yaml</code> 的顶层键，列表项再缩进一级；写进 <code>prompt:</code> 块里就只是一段文字。</li><li><strong>漏了 <code>prompt</code> 或 <code>prompt_file</code></strong>：该条目被静默跳过，父角色眼里没有这个人。</li><li><strong><code>name</code> 里带 <code>--</code></strong>：<code>--</code> 是 id 的分隔符，含它的名字会被丢掉——角色目录名（角色 id）同样不能含 <code>--</code>。</li><li><strong>两个子代理同名</strong>：后一个定义覆盖前一个，你只会得到三个人里的两个。</li><li><strong>改完 <code>role.yaml</code> 不重启</strong>：角色在启动时解析一次，当前会话不会热加载。</li><li><strong>指望子代理记得你的对话</strong>：子代理是独立会话，只看得到父角色交给它的提示词。</li></ul><h2 id="你现在拥有什么" tabindex="-1">你现在拥有什么 <a class="header-anchor" href="#你现在拥有什么" aria-label="Permalink to &quot;你现在拥有什么&quot;">​</a></h2><ul><li>一个父角色 <code>code-reviewer</code>，带技能、引用文档与自定义函数（第 02–03 章的产物）；</li><li>三名已注册的子代理：<code>code-reviewer--coder</code>、<code>code-reviewer--reviewer</code>、<code>code-reviewer--doc-writer</code>；</li><li>一句能让父角色自己拆活的提示词模板，以及「派活 → 汇总」两回合的节奏感。</li></ul><p>下一章 <a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">05 用图引擎编排团队</a>：把这条委托链路变成一张看得见的图，并学会正确地读回结果。</p><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li>子代理可以再声明 <code>subagents:</code> 形成嵌套团队；嵌套声明与 <code>subagents/&lt;名字&gt;/role.yaml</code> 文件式声明按名字合并，同名时内联优先。</li><li>文件名与目录名决定角色 id，角色 id 与子代理名字共同决定子代理 id——改名等于改 id，调用方（包括图节点里的 <code>agent</code> 字段）都要跟着改。</li></ul>`,35)])])}const g=e(t,[["render",o]]);export{k as __pageData,g as default};
